package main

import (
	"bufio"
	"fmt"
	"os"
)

func solver(n, m int) int {
	first, second := 0, 0
	copyN := n
	point := m
	if m%2 != 0 {
		point = m + 1
	}

	for copyN != point/2 {
		if copyN > point/2 {
			first += copyN - point/2
			copyN = point / 2
		}
		if copyN < point/2 {
			copyN *= 2
			first += 1
		}
	}
	if m%2 == 0 {
		first += 1
	} else {
		first += 2
	}

	copyN = n
	for copyN != m {
		if copyN < m {
			copyN *= 2
			second += 1
		} else {
			second += copyN - m
			break
		}
	}

	if first < second {
		return first
	}
	return second
}

