	in := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(in, &n, &m)

	if n > m {
		fmt.Println(n - m)
		return
	}

	data := make(map[int]int)
	data[n] = n

	find := 0
	for {
		mp := make(map[int]int)
		for x := range data {
			if x-1 >= 1 {
				mp[x-1] = x - 1
				if x-1 == m {
					fmt.Println(find + 1)
					return
				}
			}
